SELECT id FROM public.track_tournament WHERE type=$1 AND start_at= (CASE WHEN $1=2 THEN date_trunc('day',timezone('UTC',$2::text::timestamptz)-interval '6 hours') WHEN $1=0 THEN date_trunc('week',timezone('UTC',$2::text::timestamptz)-interval '6 hours') ELSE date_trunc('month',timezone('UTC',$2::text::timestamptz)-interval '6 hours') END AT TIME ZONE 'UTC')+interval '6 hours' LIMIT 1
